/** The built-in mark for an app, if there is one. "Microsoft_Teams", "microsoft-teams" and "microsoftteams" are the same app. */
export function markFor(slug: string): AppMark | null {
  return APP_MARKS[slug.toLowerCase().replace(/[^a-z0-9]/g, "")] ?? null;
}
